<template><div class="eval-page page-shell"><section class="page-hero"><div><span class="eyebrow">RAG Evaluation</span><h1 class="section-title">RAG 评测中心</h1><p class="section-desc">维护典型问题，批量检查知识库召回和来源命中情况。</p></div><el-button :loading="running" type="primary" @click="run">运行评测</el-button></section><section class="toolbar glass-panel"><el-select v-model="kbId" placeholder="选择知识库" @change="load"><el-option v-for="kb in kbs" :key="kb.id" :label="kb.name" :value="kb.id"/></el-select><el-input v-model="question" placeholder="新增评测问题" @keyup.enter="add"/><el-input v-model="source" placeholder="期望来源文件名，可选" @keyup.enter="add"/><el-button @click="add">添加</el-button></section><section class="eval-grid"><article class="glass-panel panel"><h2>评测问题</h2><el-table :data="cases"><el-table-column prop="question" label="问题" min-width="280"/><el-table-column prop="expectedSources" label="期望来源" min-width="160"/><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></article><article class="glass-panel panel"><h2>运行历史</h2><el-table :data="runs"><el-table-column prop="createTime" label="时间" min-width="160"/><el-table-column prop="totalCount" label="题数" width="70"/><el-table-column prop="hitCount" label="召回命中" width="100"/><el-table-column prop="citationHitCount" label="来源命中" width="100"/></el-table></article></section></div></template>
<script setup>
import {onMounted,ref} from 'vue';import {ElMessage} from 'element-plus';import {getKbList} from '../../api/kb';import {addEvalCase,deleteEvalCase,getEvalCases,getEvalRuns,runEval} from '../../api/eval';
const kbs=ref([]),kbId=ref(null),cases=ref([]),runs=ref([]),question=ref(''),source=ref(''),running=ref(false);onMounted(async()=>{const r=await getKbList();kbs.value=r.data||[];if(kbs.value.length){kbId.value=kbs.value[0].id;await load()}});async function load(){if(!kbId.value)return;const [a,b]=await Promise.all([getEvalCases(kbId.value),getEvalRuns(kbId.value)]);cases.value=a.data||[];runs.value=b.data||[]}async function add(){if(!question.value.trim()||!kbId.value)return;await addEvalCase({kbId:kbId.value,question:question.value,expectedSources:source.value});question.value='';source.value='';await load()}async function remove(row){await deleteEvalCase(row.id);await load()}async function run(){running.value=true;try{await runEval(kbId.value);ElMessage.success('评测完成');await load()}finally{running.value=false}}
</script><style scoped>.toolbar{display:flex;gap:10px;padding:14px;margin-bottom:18px}.eval-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.panel{padding:20px}.panel h2{margin-bottom:16px;font-size:20px}@media(max-width:760px){.toolbar,.eval-grid{grid-template-columns:1fr;display:grid}.toolbar .el-select,.toolbar .el-input{width:100%}}</style>
